"""Offline title editor. Canvas/SVG preview is explicitly schematic, not native skin rendering."""
import json
from pathlib import Path


def write_viewer(manifest):
    runtime = (Path(__file__).parent / 'title_runtime.js').read_text(encoding='utf-8')
    data = json.dumps(manifest, ensure_ascii=False).replace('</', '<\\/')
    html = r'''<!doctype html><html lang="zh-CN"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>观窗 · 军府标题编辑</title><style>
*{box-sizing:border-box}body{margin:0;background:#101820;color:#e2edf2;font:15px/1.6 system-ui,"Microsoft YaHei",sans-serif}main{max-width:1500px;margin:auto;padding:24px}h1{font-size:25px;margin:0 0 8px}p{margin:8px 0}.muted{color:#a7becb}.badge{color:#f0ca80}.grid{display:grid;grid-template-columns:minmax(0,1fr) 340px;gap:20px;margin-top:20px}.preview{background:#0a1117;border:1px solid #3d5362;border-radius:7px;overflow:hidden}svg{width:100%;height:auto;display:block}aside{background:#192934;padding:18px;border-radius:7px}label{display:block;margin:10px 0}input,button{font:inherit}input{width:100%;padding:9px;background:#0f1c25;color:#ecf5f7;border:1px solid #557385;border-radius:5px}button{padding:9px 13px;background:#9bdcc9;color:#102c2a;border:0;border-radius:5px;cursor:pointer;margin:5px 3px 5px 0}button.secondary{background:#2e4859;color:#d9e9ef;border:1px solid #567285}button:disabled{opacity:.45;cursor:wait}pre{font:12px/1.65 monospace;white-space:pre-wrap;overflow-wrap:anywhere;background:#0b151c;padding:12px;border-radius:5px}code{overflow-wrap:anywhere}.status{min-height:50px;margin-top:12px;color:#ace6cd}.error{color:#ffb4a1}.file{font-size:13px}.download{margin-top:10px}.footer{margin-top:20px;border-top:1px solid #314957;padding-top:15px}@media(max-width:900px){.grid{grid-template-columns:1fr}}</style></head><body><main>
<h1>观窗 · 实际军府主标题编辑</h1><p class="muted">读取实际GUI，修改主标题，导出保留其余源码的完整GUI草稿。</p><p class="badge">本页仅预览主窗框架与标题；背景、字体和其余控件尚未按游戏还原。导出的GUI保留整份原文件。</p>
<div class="grid"><section><div class="preview"><svg id="scene" xmlns="http://www.w3.org/2000/svg" viewBox="0 0 1760 990"><rect width="1760" height="990" fill="#0d171e"/><g id="window"><rect id="frame" fill="#1c303d" stroke="#688595" stroke-width="2"/><rect id="titleBox" fill="#284c5b" stroke="#9be6da" stroke-width="2"/><text id="titleText" fill="#f4e0a6" font-family="system-ui,Microsoft YaHei,sans-serif"></text><text id="notice" fill="#91adbc" font-size="23">其余界面在导出的GUI中原样保留，本页尚未渲染</text></g></svg></div><p class="muted" id="sourceLabel"></p><h3>本次修改</h3><pre id="diff"></pre></section>
<aside><strong>主标题 · text_single</strong><label>标题文字<input id="title" type="text" autocomplete="off"></label><label>字号<input id="font" type="number" min="1" max="4096" step="1"></label><button id="reset" class="secondary">恢复导入值</button><div class="download"><button id="export">导出完整GUI草稿</button><button id="request" class="secondary">导出编辑请求</button><button id="receipt" class="secondary">导出校验记录</button></div><label class="file">回读刚导出的GUI，核对是否与当前草稿一致<input id="reimport" type="file" accept=".gui"></label><div id="status" class="status" role="status"></div><details><summary>来源与边界</summary><pre id="identity"></pre><p class="file muted">只编辑已有标题常量与字号。模板、绑定、重复回调、窗口身份和其余源码不变。导出文件不会自动安装，也不会操作游戏。</p></details></aside></div>
<div class="footer muted">GUI草稿可独立保存；编辑请求也可交给项目CLI重新解析、验证并生成带diff的候选包。本页回读验证逐字节一致，完整语法解析与游戏渲染是另外两项验证。</div>
</main><script id="manifest" type="application/json">__MANIFEST__</script><script>__RUNTIME__</script><script>
const M=JSON.parse(document.getElementById('manifest').textContent),G=GuanchuangTitle,$=id=>document.getElementById(id);
let revision=0,lastResult=null,pending=null;
function changes(){const c={},title=$('title').value,size=Number($('font').value);G.literal(title);G.font(size);if(title!==M.fields.raw_text.value)c.raw_text=title;if(size!==M.fields.fontsize.value)c.fontsize=size;return c}
function status(text,error=false){$('status').textContent=text;$('status').className='status'+(error?' error':'')}
function draw(){const [w,h]=M.preview.root_size,[x,y,tw,th]=M.preview.title_rect_local;const centered=M.preview.root_anchor==='center',ox=centered?(1760-w)/2:0,oy=centered?(990-h)/2:0;$('window').setAttribute('transform',`translate(${ox},${oy})`);for(const[k,v]of Object.entries({x:0,y:0,width:w,height:h}))$('frame').setAttribute(k,v);for(const[k,v]of Object.entries({x,y,width:tw,height:th}))$('titleBox').setAttribute(k,v);$('titleText').setAttribute('x',x);$('titleText').setAttribute('y',y+th/2);$('titleText').setAttribute('dominant-baseline','central');$('titleText').setAttribute('font-size',$('font').value);$('titleText').textContent=$('title').value;$('notice').setAttribute('x',44);$('notice').setAttribute('y',140)}
async function refresh(){const r=++revision;lastResult=null;try{const c=changes();draw();$('diff').textContent=Object.keys(c).length?Object.entries(c).map(([k,v])=>`${k}: ${JSON.stringify(M.fields[k].value)} → ${JSON.stringify(v)}`).join('\n'):'尚未修改；导出将逐字节保留原文件。';const result=await G.apply(M,G.request(M,c));if(r!==revision)return;lastResult=result;status(result.receipt.patches.length?`草稿已准备：${result.receipt.patches.length}个源码token改变，其余字节保留。`:'原始GUI已校验，尚未修改。');document.body.dataset.ready='1';document.body.dataset.patchCount=String(result.receipt.patches.length)}catch(e){if(r!==revision)return;status(e.message,true);$('diff').textContent='当前输入无法导出。'}}
function update(){pending=refresh();return pending}
async function current(){await pending;if(!lastResult)throw new Error('请先修正编辑值');return lastResult}
function download(name,blob){const a=document.createElement('a'),url=URL.createObjectURL(blob);a.href=url;a.download=name;a.click();URL.revokeObjectURL(url)}
function jsonDownload(name,value){download(name,new Blob([JSON.stringify(value,null,2)],{type:'application/json;charset=utf-8'}))}
$('title').value=M.fields.raw_text.value;$('font').value=String(M.fields.fontsize.value);$('sourceLabel').textContent=`${M.source}:${M.owner_line} · ${M.window} · 原始 SHA256 ${M.base_sha256.slice(0,16)}…`;$('identity').textContent=JSON.stringify({source:M.source,owner:M.owner_id,base_sha256:M.base_sha256,integrity:M.integrity,preview:M.preview.mode},null,2);
$('title').oninput=update;$('font').oninput=update;$('reset').onclick=()=>{$('title').value=M.fields.raw_text.value;$('font').value=String(M.fields.fontsize.value);return update()};
$('export').onclick=async()=>{try{const r=await current();download(M.source.split('/').pop(),new Blob([r.bytes],{type:'application/octet-stream'}));status('GUI草稿已交给浏览器保存；Mod安装目录未修改。')}catch(e){status(e.message,true)}};
$('request').onclick=async()=>{try{jsonDownload('title-edit-request.json',(await current()).request)}catch(e){status(e.message,true)}};
$('receipt').onclick=async()=>{try{jsonDownload('title-edit-receipt.json',(await current()).receipt)}catch(e){status(e.message,true)}};
$('reimport').onchange=async e=>{try{const f=e.target.files[0];if(!f)return;const actual=new Uint8Array(await f.arrayBuffer()),expected=await current();if(!G.equal(actual,expected.bytes))throw new Error('回读文件与当前草稿不同；未替换当前编辑内容');status(`回读通过：${actual.length}字节与当前草稿完全一致。完整语法/游戏渲染需另行验证。`);document.body.dataset.reimport='PASS'}catch(e){status(e.message,true);document.body.dataset.reimport='FAIL'}};
update();
</script></body></html>'''
    return html.replace('__RUNTIME__', runtime).replace('__MANIFEST__', data)
